INSERT INTO `1_carrusel` (`id`, `imagen`, `titulo`, `subtitulo`, `url`, `boton`, `orden`, `estado`, `fecha`, `cedula`) VALUES
(1, 'http://127.0.0.1:8000/imagenes_carrusel/1769517831_VID_20260122_213015.mp4', 'SOMOS PLEXA', 'Cuando la logística es clave, la energía fluye.\nTransportamos gases derivados del petróleo e hidrocarburos garantizando continuidad y desempeño operacional', '#', 'Leer Más', 1, 1, '2025-12-30 09:25:00', 1047418839),
(2, 'http://127.0.0.1:8000/imagenes_carrusel/1777581675_PLEXA-19.jpg', 'Comercialización y Logistica de GLP', 'Años de experiencia aportando valor al desarrollo del mercado de Gas Licuado del Petróleo (GLP), con enfoque en eficiencia, seguridad y continuidad operativa.', 'comerciylog', 'Leer Más', 2, 1, '2025-12-30 11:05:51', 1047418839),
(3, 'http://plexa.co/wp-content/uploads/2025/04/DJI_0706-scaled.jpg', 'Arbitraje Logístico', 'Plexa brinda la Solución Energética que su negocio necesita. Desde la fuente hasta el punto de entrega.', 'arbitrajelogistico', 'Leer Más', 3, 1, '2025-12-30 11:10:17', 1047418839),
(4, 'http://plexa.co/wp-content/uploads/2025/04/plexaport.jpg', 'PLEXAPORT', 'Capacidad de almacenamiento por 25.000 Barriles de Gases Combustibles, para una operación segura y eficiente\n ', 'plexaport', 'Leer Más', 5, 1, '2025-12-30 11:10:17', 1047418839),
(5, 'https://yegoecot.com/wp-content/uploads/2024/01/AND09802.jpg', 'Yego Eco-T', 'Yego Ecot es una empresa visionaria dedicada al transporte masivo y semimasivo en Colombia. Con una flota propia de vehículos a GNV, lideramos la transición hacia combustibles amigables con el medio ambiente. Descubre nuestra historia, compromiso y visión', 'https://yegoecot.com/', 'Leer Más', 10, 0, '2025-12-30 11:12:29', 1047418839),
(6, 'https://yego.com.co/wp-content/uploads/2024/12/DSC01368-1.jpg', 'Yego AutoGLP', 'Ahorra más, contamina menos Hasta 35% de ahorro con AutoGLP.', 'https://yego.com.co/', 'Leer Más', 7, 0, '2025-12-30 11:12:29', 1047418839),
(7, 'http://127.0.0.1:8000/imagenes_carrusel/1775660074_Veh__culo_Chile.png', 'CHILE', '', 'chile', 'Leer Más', 12, 1, '2025-12-30 09:25:00', 1047418839),
(9, 'http://127.0.0.1:8000/imagenes_carrusel/1777584432_123_-_copia.png', 'PP Navigation', 'Transporte Multimodal, Terrestre y fluvial', 'arbitrajelogistico', 'Leer Más', 6, 1, '2026-01-23 08:12:16', 1041972451),
(10, 'http://127.0.0.1:8000/imagenes_carrusel/1777581935_PLEXA-13.jpg', 'Trading GLP y GN', 'Trading de GLP y Gas Natural que conecta mercados, optimiza costos y asegura energía confiable.', 'tradingglp', 'Leer Más', 4, 1, '2026-02-24 08:45:46', 1041972451);
